/* Original teaching content. Short consolidation lessons, not a substitute for the school's full scheme. */
const SCHOOL_LESSONS=[];
function SL(id,subject,title,years,explain,worked,mistake,tryIt,model,questions){SCHOOL_LESSONS.push({id,subject,title,years,explain,worked,mistake,tryIt,model,qs:questions.map((a,i)=>({id:'school_'+id+'_'+i,question:a[0],correct:String(a[1]),options:[String(a[1]),...a.slice(2,5).map(String)],explanation:a[5]||('Use the lesson rule. The correct answer is '+a[1]+'.')}))})}
const Y=[3,4,5,6];
SL('place3','Mathematics','Place value: hundreds, tens and ones',[3],['The position of a digit tells you its value. A hundred is ten tens. A ten is ten ones.','Partitioning means splitting a number into its place-value parts. Compare hundreds first, then tens, then ones.'],['In 462: 4 hundreds = 400, 6 tens = 60, 2 ones = 2. So 462 = 400 + 60 + 2.','Compare 374 and 347: hundreds match. Seven tens is greater than four tens, so 374 > 347.'], 'In 507, the 0 holds the tens place. The 5 means 500, not 50.','Write 683 in expanded form. Then write a number with 5 hundreds, 0 tens and 9 ones.','683 = 600 + 80 + 3. The second number is 509.',[['What is the value of 7 in 572?',70,7,700,72,'The 7 is in the tens place: seven tens = 70.'],['Which number is 400 + 30 + 8?',438,483,4038,348,'Combine 4 hundreds, 3 tens and 8 ones.'],['Which is greatest?',629,596,602,620,'All but 596 have 6 hundreds. Compare tens: 2 > 0, then ones: 9 > 0.'],['What is 100 more than 356?',456,366,256,1356,'Increase the hundreds by one.'],['What is 10 less than 402?',392,401,302,412,'Exchange one hundred for ten tens, then subtract one ten.']]);
for(let y of [4,5,6]){let place=y===4?1000:y===5?100000:1000000,limit=y===4?'thousands':y===5?'millions':'ten millions';SL('place'+y,'Mathematics','Place value and rounding to '+limit,[y],['Each step left makes a place ten times larger. Zero holds a place when there are no units of that size.','To round, locate the rounding place and look one place to the right. 5 or more: round up; 4 or less: round down.'],[`In ${3*place+42}, the digit 3 represents ${3*place}.`,`Round 3,647 to the nearest hundred: the tens digit is 4, so the answer is 3,600.`],'Check the rounding place before looking at the next digit. Rounding to 10 and rounding to 100 can give different answers.','Round 4,786 to the nearest ten, hundred and thousand. Explain which digit decides each answer.','Nearest ten: 4,790. Hundred: 4,800. Thousand: 5,000.',[['Round 2,463 to the nearest hundred.',2500,2400,2460,2000,'The tens digit is 6, so 2,463 rounds up to 2,500.']]);let l=SCHOOL_LESSONS.at(-1);l.qs[0].correct='2500';l.qs[0].options=['2500','2400','2460','2000'];for(let i=1;i<=4;i++){let n=place*(i+2)+71;l.qs.push({id:'school_place'+y+'_'+i,question:`What is the value of ${i+2} in ${n.toLocaleString('en-GB')}?`,correct:String(place*(i+2)),options:[place*(i+2),i+2,10*(i+2),100*(i+2)].map(String),explanation:`The digit is in the ${place.toLocaleString('en-GB')} place. Multiply ${i+2} by ${place}.`})}}
SL('addition','Mathematics','Column addition and subtraction',Y,['Line up digits by place value. Work from ones to tens to hundreds.','When a column totals 10 or more, exchange 10 units for 1 in the next column. For subtraction, exchange from the next column when needed.'],['347 + 286: 7 + 6 = 13. Write 3 ones and carry 1 ten. Tens: 4 + 8 + 1 = 13. Write 3 tens and carry 1 hundred. Hundreds: 3 + 2 + 1 = 6. Answer: 633.','532 − 178: exchange a ten to make 12 ones; 12 − 8 = 4. Now there are 2 tens, so exchange a hundred: 12 tens − 7 tens = 5 tens. Hundreds: 4 − 1 = 3. Answer: 354.'],'Do not subtract the smaller digit from the larger automatically. The order in the question matters.','Calculate 458 + 267 and 621 − 285. Show exchanges. Check the subtraction by adding back.','458 + 267 = 725. 621 − 285 = 336. Check: 336 + 285 = 621.',[['Calculate 236 + 157.',393,383,303,493,'Ones: 6 + 7 = 13. Tens: 3 + 5 + 1 = 9. Hundreds: 2 + 1 = 3.'],['Calculate 502 − 168.',334,466,344,434,'Exchange across the zero. Check 334 + 168 = 502.'],['Calculate 409 + 286.',695,685,605,795,'Add aligned columns and carry from the ones.'],['Calculate 700 − 256.',444,454,544,556,'700 − 200 = 500; −50 = 450; −6 = 444.'],['Which checks 642 − 275 = 367?', '367 + 275 = 642','642 + 275 = 367','367 − 275 = 642','642 + 367 = 275','Subtraction is checked using its inverse, addition.']]);
for(let y of Y){let tables=y===3?[3,4,8]:[6,7,9,12];SL('times'+y,'Mathematics',y===3?'3, 4 and 8 times tables':'Multiplication and division facts',[y],['Multiplication describes equal groups. Division can find the number of groups or the size of each group.','A fact family connects multiplication and division. Use a known fact to derive another.'],['4 × 6 means 4 groups of 6. Double 2 × 6 = 12 to get 4 × 6 = 24.','8 × 5 = 40, so 40 ÷ 8 = 5 and 40 ÷ 5 = 8.'],'Multiplication groups must be equal. Division is not commutative: 24 ÷ 6 differs from 6 ÷ 24.','Draw an array for 4 × 7. Write two multiplication and two division facts.','4 × 7 = 28; 7 × 4 = 28; 28 ÷ 4 = 7; 28 ÷ 7 = 4.',Array.from({length:6},(_,i)=>{let a=tables[i%tables.length],b=i+3;return i%2?[`Calculate ${a*b} ÷ ${a}.`,b,b+1,b-1,b+2,`${a} × ${b} = ${a*b}, so division gives ${b}.`]:[`Calculate ${a} × ${b}.`,a*b,a*b+a,a*b-a,a*b+1,`${a} equal groups of ${b} make ${a*b}.`]}))}
SL('fractions','Mathematics','Fractions: equal parts and amounts',Y,['The denominator tells how many equal parts make one whole. The numerator tells how many parts are selected.','To find a fraction of an amount, divide by the denominator, then multiply by the numerator.'],['Three quarters of 20: 20 ÷ 4 = 5 in each quarter. Then 5 × 3 = 15.','One half equals two quarters because both cover the same amount of the whole.'],'The parts must be equal. A larger denominator does not mean a larger unit fraction.','Draw a bar split into 8 equal parts and shade 3. Find 3/4 of 28.','Shade 3 of the 8 parts. 28 ÷ 4 = 7; 7 × 3 = 21.',[['What is 1/4 of 24?',6,4,8,12,'24 divided into 4 equal groups gives 6 per group.'],['What is 2/3 of 18?',12,6,9,15,'18 ÷ 3 = 6; 6 × 2 = 12.'],['Which equals 1/2?','3/6','1/3','2/6','3/4','Multiply numerator and denominator by 3.'],['In 3/8, how many equal parts make the whole?',8,3,5,11,'The denominator 8 counts the equal parts.'],['Which is greater: 1/3 or 1/6?','1/3','1/6','They are equal','Cannot compare','With the same whole, splitting into 3 parts gives larger pieces than splitting into 6.']]);
SL('decimals','Mathematics','Decimals, tenths and hundredths',[4,5,6],['The first place after the decimal point is tenths; the next is hundredths. Ten hundredths equal one tenth.','Compare by aligning decimal points and filling empty places with zeros. Trailing zeros do not change the value.'],['0.6 = 0.60. Compare 0.60 with 0.56: 6 tenths is greater than 5 tenths, so 0.6 > 0.56.','37 hundredths = 37/100 = 0.37.'],'0.8 is greater than 0.75. Counting digits after the decimal point does not tell which is larger.','Put 0.4, 0.35 and 0.09 in ascending order. Explain the value of 7 in 2.73.','0.09 < 0.35 < 0.4. The 7 represents seven tenths, or 0.7.',[['Which is greatest?','0.7','0.65','0.09','0.07','0.7 = 0.70, greater than 0.65.'],['Write 9/100 as a decimal.','0.09','0.9','9.0','0.009','Hundredths occupy the second decimal place.'],['What is 0.3 + 0.4?','0.7','0.12','0.07','7','3 tenths + 4 tenths = 7 tenths.'],['Which equals 0.50?','1/2','1/5','5','1/50','50 hundredths equals one half.'],['What is 2.6 + 0.25?','2.85','2.31','2.625','2.75','Align decimal points: 2.60 + 0.25 = 2.85.']]);
SL('measure','Mathematics','Measurement and unit conversions',Y,['A measurement needs a number and a unit. Choose a suitable unit for what you measure.','1 m = 100 cm; 1 cm = 10 mm; 1 kg = 1,000 g; 1 litre = 1,000 ml. To convert into smaller units, multiply by the number of those units in one larger unit.'],['3 m 25 cm = 300 cm + 25 cm = 325 cm.','2 kg 40 g = 2,000 g + 40 g = 2,040 g.'],'Do not write 2 kg 40 g as 240 g. There are 1,000 grams in each kilogram.','Convert 4 m 8 cm to centimetres and 1 litre 250 ml to millilitres.','408 cm and 1,250 ml.',[['How many centimetres are in 2 m?',200,20,2000,2,'Each metre has 100 cm.'],['How many grams are in 3 kg?',3000,300,30,30000,'Each kilogram contains 1,000 grams.'],['Which is suitable for the mass of an apple?','grams','litres','kilometres','degrees','Grams measure mass.'],['How many millilitres are in half a litre?',500,50,5,5000,'1 litre = 1,000 ml, so half is 500 ml.'],['How many millimetres are in 7 cm?',70,7,700,17,'7 × 10 = 70.']]);
SL('area','Mathematics','Perimeter and area',[4,5,6],['Perimeter is the total distance around a shape. Area is the space inside it.','For a rectangle, perimeter = 2 × (length + width). Area = length × width. Area uses square units.'],['A 6 cm by 4 cm rectangle has perimeter 6 + 4 + 6 + 4 = 20 cm.','Its area is 6 × 4 = 24 cm²: 24 unit squares cover it.'],'Do not give area in cm or perimeter in cm². They describe different measurements.','Draw a rectangle 8 cm by 3 cm. Find and label its perimeter and area.','Perimeter = 22 cm. Area = 24 cm².',[['Area of a rectangle 7 cm by 3 cm?','21 cm²','20 cm','10 cm²','21 cm','7 × 3 = 21 square centimetres.'],['Perimeter of a square with sides 5 cm?','20 cm','25 cm²','10 cm','5 cm','Four equal sides: 4 × 5 = 20.'],['Perimeter of a 9 m by 2 m rectangle?','22 m','18 m²','11 m','18 m','2 × (9 + 2) = 22 m.'],['Area of a 4 m by 4 m square?','16 m²','16 m','8 m²','4 m²','4 × 4 = 16 square metres.'],['Which measures distance around a shape?','Perimeter','Area','Volume','Mass','Perimeter follows the outside boundary.']]);
SL('time','Mathematics','Telling time and elapsed time',Y,['There are 60 minutes in one hour. The long clock hand shows minutes; each numbered interval is 5 minutes.','Elapsed time is the duration between a start and finish. Count to the next hour, then to the finishing time.'],['From 2:45 pm to 3:20 pm: 15 minutes to 3:00, then 20 more minutes. Total = 35 minutes.','Quarter past 6 is 6:15. Quarter to 7 is 6:45.'],'An hour is 60 minutes, not 100. 2:50 plus 20 minutes is 3:10.','A lesson starts at 9:40 am and finishes at 10:25 am. How long is it?','20 minutes to 10:00 plus 25 minutes = 45 minutes.',[['How many minutes are in 2 hours?',120,100,60,200,'2 × 60 = 120.'],['What is quarter to 5?','4:45','5:15','5:45','4:15','15 minutes before 5 is 4:45.'],['How long from 10:50 to 11:15?','25 minutes','65 minutes','35 minutes','15 minutes','10 minutes to 11:00 plus 15 minutes.'],['What is 30 minutes after 2:45?','3:15','2:75','3:45','2:15','15 minutes reaches 3:00, then 15 more reaches 3:15.'],['What is 15:30 in 12-hour time?','3:30 pm','3:30 am','5:30 pm','12:30 pm','For times after noon, subtract 12 from the hour.']]);
SL('money','Mathematics','Money and giving change',Y,['£1 is 100 pence. Write pounds and pence with two decimal places: £2.05 is two pounds and five pence.','To find change, subtract the cost from the amount paid, or count up from the cost.'],['Pay £5 for a £3.65 item. Count up: 35p to £4, then £1 to £5. Change is £1.35.','£1.20 + 75p: 120p + 75p = 195p = £1.95.'],'£2.05 is 205p, not 25p. Keep pounds and pence in consistent units.','A book costs £4.75. You pay £10. Show how to work out the change.','25p to £5 plus £5 to £10 gives £5.25.',[['How many pence is £3.40?',340,34,304,3400,'3 pounds = 300p, plus 40p.'],['Change from £2 after spending 65p?','£1.35','£1.45','£1.65','£0.35','200p − 65p = 135p.'],['£1.50 + £2.25 = ?','£3.75','£3.65','£4.75','£2.75','150p + 225p = 375p.'],['Which is the same as 7p?','£0.07','£0.70','£7.00','£0.007','Seven hundredths of a pound is £0.07.'],['Three items cost 40p each. Total?','£1.20','£0.43','£1.40','£0.80','3 × 40p = 120p.']]);
SL('angles','Mathematics','Angles and shape properties',Y,['An angle measures a turn. A right angle is 90°. An acute angle is smaller than 90°; an obtuse angle is between 90° and 180°.','A straight angle is 180°. A complete turn is 360°. Use known totals to find missing angles.'],['Angles on a straight line add to 180°. If one is 65°, the other is 180 − 65 = 115°.','A square has four equal sides and four right angles. A rectangle has four right angles, but its sides need not all be equal.'],'An angle does not become bigger when you draw longer arms. The amount of turn matters.','Draw an acute angle and an obtuse angle. Find the missing angle on a straight line if the other is 120°.','Examples: 45° is acute; 110° is obtuse. Missing angle = 60°.',[['How many degrees in a right angle?',90,45,180,360,'A quarter turn is 90°.'],['Which is an acute angle?','35°','90°','120°','180°','35° is less than 90°.'],['Angles on a straight line total?',180,90,270,360,'A half turn equals 180°.'],['Which shape always has four equal sides and four right angles?','Square','Any rectangle','Any trapezium','Triangle','A square has both properties.'],['A straight line has one angle of 70°. Find the other.',110,70,20,290,'180 − 70 = 110°.']]);
SL('statistics','Mathematics','Tables, graphs and interpreting data',Y,['Data are collected facts or measurements. Tables organise data; graphs help compare values.','Always read the title, labels, units and scale. Each marked step may represent more than one.'],['A bar chart counts pets: cats 8, dogs 12, rabbits 4. Most common: dogs. Total = 8 + 12 + 4 = 24.','Difference between dogs and cats = 12 − 8 = 4.'],'Do not assume each grid line means 1. Check the scale before reading a bar.','Use the pet data above. How many more cats than rabbits are there? What fraction of the 24 pets are dogs?','4 more cats; 12/24 = 1/2 are dogs.',[['Scores are 6, 9 and 5. What is the total?',20,19,21,15,'6 + 9 + 5 = 20.'],['A scale is marked 0, 5, 10, 15. Each interval represents?',5,1,10,15,'The difference between adjacent marks is 5.'],['Red: 7, blue: 11, green: 6. Which is most common?','Blue','Red','Green','All equal','11 is the largest count.'],['How many more blue (11) than green (6)?',5,17,6,4,'Find the difference: 11 − 6 = 5.'],['What should a graph axis include?','A clear label and suitable scale','Only decoration','An unrelated title','No numbers','Labels and scale let you interpret the values.']]);
SL('percent','Mathematics','Percentages and equivalent fractions',[5,6],['Percent means out of 100. 50% = 1/2, 25% = 1/4 and 10% = 1/10.','Find 10% by dividing by 10; find 1% by dividing by 100. Combine parts for other percentages.'],['15% of 80: 10% = 8, 5% = 4, so 15% = 12.','3/4 = 75/100 = 75% = 0.75.'],'10% is not always 10. It depends on the amount you are finding a percentage of.','Find 20% of 150 and explain how you did it. Convert 2/5 to a percentage.','10% of 150 is 15; double gives 30. 2/5 = 40/100 = 40%.',[['25% of 60?',15,25,20,30,'A quarter of 60 is 15.'],['10% of 240?',24,10,2.4,2400,'Divide 240 by 10.'],['1/2 as a percentage?','50%','2%','25%','20%','Half of 100 is 50.'],['0.3 as a percentage?','30%','3%','0.3%','300%','0.3 = 30 hundredths.'],['20% of 90?',18,20,9,45,'10% is 9, so 20% is 18.']]);
SL('ratio','Mathematics','Ratio and proportion',[6],['A ratio compares quantities in parts. A red:blue ratio of 2:3 means 2 red parts for every 3 blue parts.','To share a total, add ratio parts, divide the total by that sum, then multiply by each part count.'],['Share 30 in ratio 2:3. There are 5 parts. Each part is 30 ÷ 5 = 6. Shares: 12 and 18.','A recipe for 4 uses 200 g flour. For 6, use 200 ÷ 4 × 6 = 300 g.'],'2:3 does not mean two thirds of the total is red. Red is 2 of 5 total parts.','Share 42 counters in a ratio of 3:4. Check the total.','7 parts; each is 6. Shares 18 and 24; 18 + 24 = 42.',[['Share 20 in ratio 1:3. Smaller share?',5,10,4,15,'4 parts; 20 ÷ 4 = 5.'],['Ratio 2:5. How many total parts?',7,10,3,5,'2 + 5 = 7.'],['A recipe uses 100 g for 2 people. For 6 people?',300,200,600,150,'6 people is 3 times as many.'],['Share 35 in ratio 2:3. Larger share?',21,14,15,20,'5 parts; each 7. Larger share = 3 × 7.'],['Simplify 6:9.','2:3','3:2','1:3','6:3','Divide both parts by 3.']]);
SL('algebra','Mathematics','Algebra and missing numbers',[6],['A letter can stand for an unknown number. An equation says two expressions have equal values.','Keep an equation balanced: do the same operation to each side. Undo operations in reverse order.'],['Solve 3x + 2 = 17. Subtract 2: 3x = 15. Divide by 3: x = 5. Check: 3 × 5 + 2 = 17.','If a = 4, then 2a + 3 = 2 × 4 + 3 = 11.'],'3x means 3 multiplied by x, not 3 plus x.','Solve 4x − 3 = 21. Then check by substitution.','Add 3: 4x = 24. Divide by 4: x = 6. Check: 24 − 3 = 21.',[['x + 7 = 19. Find x.',12,26,11,7,'Subtract 7 from each side.'],['3x = 24. Find x.',8,21,72,6,'Divide both sides by 3.'],['If a = 5, what is 2a + 1?',11,8,12,10,'2 × 5 + 1 = 11.'],['2x + 4 = 18. Find x.',7,11,9,14,'Subtract 4, then divide by 2.'],['What does 4n mean?','4 multiplied by n','4 plus n','n divided by 4','4 minus n','A number beside a letter indicates multiplication.']]);
SL('multiply','Mathematics','Written multiplication and division',[4,5,6],['Partition a number to multiply it in manageable parts. Place value explains why a second row for tens needs a zero placeholder.','For division, share each place in turn and exchange remainders into the next place. Check with multiplication.'],['23 × 14 = 23 × (10 + 4) = 230 + 92 = 322.','156 ÷ 3: 15 tens ÷ 3 = 5 tens; 6 ones ÷ 3 = 2 ones. Answer 52. Check 52 × 3 = 156.'],'In 23 × 14, the 1 stands for 10. A row for ×10 is 230, not 23.','Calculate 34 × 12 and 168 ÷ 4. Show each step.','34 × 10 + 34 × 2 = 340 + 68 = 408. 168 ÷ 4 = 42.',[['24 × 13 = ?',312,132,288,302,'24 × 10 = 240; 24 × 3 = 72; total 312.'],['144 ÷ 4 = ?',36,34,32,46,'120 ÷ 4 = 30; 24 ÷ 4 = 6.'],['In 42 × 15, what is 42 × 10?',420,42,4200,52,'Multiplying by ten makes each digit worth ten times as much.'],['21 × 16 = ?',336,326,126,316,'210 + 126 = 336.'],['225 ÷ 5 = ?',45,40,55,35,'200 ÷ 5 = 40 and 25 ÷ 5 = 5.']]);
SL('fractioncalc','Mathematics','Adding and subtracting fractions',[4,5,6],['With equal denominators, add or subtract numerators and keep the denominator. The size of each part stays the same.','For unlike denominators, rename fractions as equivalent fractions with a common denominator before calculating.'],['2/7 + 3/7 = 5/7. We have five sevenths, not five fourteenths.','1/2 + 1/4 = 2/4 + 1/4 = 3/4.'],'Do not add denominators. 1/3 + 1/3 = 2/3, not 2/6.','Calculate 3/8 + 2/8. Then calculate 3/4 − 1/2. Explain how you make the parts equal.','5/8. Then 3/4 − 2/4 = 1/4.',[['1/5 + 2/5 = ?','3/5','3/10','2/5','1/5','Add the number of fifths: 1 + 2 = 3.'],['5/8 − 2/8 = ?','3/8','3/0','7/8','3/16','5 eighths minus 2 eighths is 3 eighths.'],['1/2 + 1/4 = ?','3/4','2/6','1/6','1/8','Rename 1/2 as 2/4.'],['2/3 equals how many sixths?','4/6','2/6','3/6','5/6','Multiply numerator and denominator by 2.'],['3/4 − 1/4 = ?','1/2','2/0','1/4','1','2/4 simplifies to 1/2.']]);
SL('order','Mathematics','Order of operations',[6],['Brackets are evaluated first. Then multiplication and division, from left to right. Finally addition and subtraction, from left to right.','Operations at the same priority are not done in a fixed letter order: use left to right.'],['3 + 4 × 5 = 3 + 20 = 23. But (3 + 4) × 5 = 7 × 5 = 35.','24 ÷ 6 × 2 = 4 × 2 = 8. Division and multiplication have equal priority.'],'Do not always calculate strictly from the first symbol, and do not always multiply before dividing.','Work out 8 + 3 × 4 and (8 + 3) × 4. Explain the difference.','20 and 44. Brackets change what is calculated first.',[['5 + 2 × 6 = ?',17,42,16,32,'Multiply first: 12 + 5 = 17.'],['(5 + 2) × 6 = ?',42,17,37,30,'Brackets first: 7 × 6 = 42.'],['18 ÷ 3 × 2 = ?',12,3,6,27,'Same priority: left to right, 6 × 2 = 12.'],['20 − 8 ÷ 4 = ?',18,3,12,5,'Division first: 20 − 2 = 18.'],['7 × (9 − 5) = ?',28,58,23,63,'Brackets: 9 − 5 = 4, then multiply.']]);
SL('reading','English','Reading comprehension: retrieval and inference',Y,['Retrieval means finding information that is stated in a text. Inference means combining clues with what you know to work out something unstated.','Explain an inference using evidence: I think… because the text says… Do not add an idea that the text does not support.'],['Text: Mia gripped her ticket. When the train doors opened, she smiled and hurried forward. Retrieval: What did Mia hold? A ticket.','Inference: How might Mia feel? Eager or excited, because she smiled and hurried towards the train. We cannot tell her destination from this text.'],'An inference is supported by clues. A guess with no evidence is not enough.','Text: Rain tapped the window. Leo put away his football and opened a book. Write one retrieval question and one inference, with evidence.','Retrieval: What did Leo open? A book. Inference: He may have changed his plan because of the rain; he put away the football and chose an indoor activity.',[['Text: Sam wore a coat and gloves. What did Sam wear?','A coat and gloves','A swimming costume','A helmet','A scarf only','The information is explicitly stated.'],['Text: Aisha checked the clock three times and tapped her foot. What is a supported inference?','She may be impatient','She definitely has a dog','She is asleep','She lives in London','Repeated clock-checking and foot-tapping suggest impatience.'],['Which answer uses evidence?','He may be cold because he is shivering.','He is cold because I say so.','He must like ice cream.','He is definitely ten.','The physical clue supports the inference.'],['Text: Ben put his wet umbrella by the door. What was wet?','The umbrella','The door','His book','His lunch','Retrieve the named item.'],['What is retrieval?','Finding stated information','Inventing a new ending','Guessing without clues','Counting all the verbs','Retrieval locates explicit information.']]);
SL('wordclass','English','Grammar: nouns, verbs and adjectives',Y,['A noun names a person, place, thing or idea. A verb can express an action or a state, such as run or be.','An adjective describes a noun. To identify a word class, look at how the word works in its sentence.'],['The small bird sings. Bird is a noun; small is an adjective describing bird; sings is the verb.','In I drink water, drink is a verb. In I want a drink, drink is a noun. Context matters.'],'Not every verb is an action you can see. Is, seems and knows can also be verbs.','Write a sentence containing a noun, verb and two adjectives. Underline and label them.','The bright, tiny butterfly landed. Butterfly: noun; landed: verb; bright and tiny: adjectives.',[['In “The red kite flew”, which is the adjective?','red','kite','flew','The','Red describes kite.'],['In “Ella opens the box”, which is the verb?','opens','Ella','the','box','Opens expresses the action.'],['Which word is a noun in “The teacher smiled”?','teacher','smiled','The','quietly','Teacher names a person.'],['In “The soup is hot”, is “is” a verb?','Yes, it expresses a state','No, it is a noun','No, it is an adjective','No, only running can be a verb','Be and its forms are verbs.'],['In “I want a drink”, drink is a…','noun','verb','adjective','conjunction','It names a thing in this sentence.']]);
SL('punctuation','English','Capital letters, full stops and sentence punctuation',Y,['Begin sentences with a capital letter. Use capitals for proper names and the pronoun I.','A full stop ends a statement. A question mark ends a direct question. An exclamation mark can show strong feeling.'],['Incorrect: my friend sara lives in poole. Correct: My friend Sara lives in Poole.','Where is my coat? is a direct question, so it ends with a question mark.'],'A capital letter is not needed for every important-looking word. A question mark belongs to a question, not every sentence containing a question word.','Correct: on monday i visited london with amy. Then write a question about the visit.','On Monday I visited London with Amy. Example: What did you see in London?',[['Which is correctly written?','I live in Poole.','i live in poole.','I Live In Poole.','i live in Poole','Capitalise I, the place name and sentence beginning.'],['Which punctuation ends “Where is the library”?','?','.','!',',','It is a direct question.'],['Which word needs a capital in “We met anna”?','Anna','met','We only','All words','A personal name is a proper noun.'],['Which is a complete statement?','The train arrived.','the train arrived','The train arrived?','the Train Arrived,','Capital letter and full stop mark the statement.'],['Which pronoun is always capitalised in standard written English?','I','he','they','we','The first-person singular pronoun I uses a capital.']]);
SL('conjunction','English','Conjunctions and joining clauses',Y,['A clause usually contains a verb. A conjunction joins words, phrases or clauses.','And adds information, but introduces contrast and because introduces a reason. When, if and although can begin subordinate clauses.'],['I took an umbrella because it was raining. Because introduces the reason.','Although it was raining, we walked to school. The subordinate clause gives background contrast; we walked to school is the main clause.'],'Choose a conjunction that matches the meaning. Do not join every sentence with and.','Join these ideas using because: The soil was dry. We watered the plants. Then write a sentence beginning Although.','We watered the plants because the soil was dry. Although it was cold, we played outside.',[['Which conjunction introduces a reason?','because','but','or','and','Because explains why.'],['Complete: “I was tired, ___ I finished my work.”','but','because','if','when','But introduces a contrast.'],['Which word joins choices?','or','because','although','when','Or presents alternatives.'],['Which is the main clause in “When the bell rang, we left”?','we left','When','the bell','When the bell','We left can stand as a sentence.'],['Complete: “Take a coat ___ it is cold.”','because','but','or','although','The cold is the reason for taking a coat.']]);
SL('apostrophe','English','Apostrophes: contractions and possession',Y,['A contraction joins words and uses an apostrophe for missing letters: do not becomes don’t.','Possession shows belonging: the girl’s bag belongs to one girl; the girls’ bags belong to more than one girl. Irregular plurals can take ’s, as in children’s.'],['It is cold → It’s cold. The apostrophe replaces the missing i in is.','One dog has a bowl → the dog’s bowl. Several dogs have bowls → the dogs’ bowls.'],'Do not add an apostrophe just to make a plural. Its means belonging to it; it’s means it is or it has.','Rewrite: The coat of one teacher. Rewrite: The books of several pupils. Then shorten we are.','The teacher’s coat. The pupils’ books. We’re.',[['Shorten “do not”.',"don’t","dont","do’nt","do not’s",'The apostrophe marks the omitted o.'],['A bag belonging to one girl is…',"the girl’s bag","the girls bag","the girls’ bag","the girl bag’s",'Singular owner: add apostrophe + s.'],['Which is a plain plural?','cats',"cat’s","cats’","cat’s’",'A plural alone does not need an apostrophe.'],['Choose: “The dog wagged ___ tail.”','its',"it’s","its’","it",'Its shows possession.'],['Books belonging to several teachers are…',"the teachers’ books","the teacher’s books","the teachers books’","the teacher books",'For a plural ending in s, add the apostrophe after s.']]);
SL('tense','English','Verb tenses: past, present and present perfect',Y,['Tense helps place events in time. Present simple describes routines or facts; past simple describes completed past events.','The present perfect uses have or has plus a past participle. It can connect a past action with now: I have lost my key means it is still missing.'],['Every day she walks. Yesterday she walked. Walk changes to walked for the regular past form.','I have finished my work. Have + finished forms the present perfect. I finished it yesterday uses past simple with a finished time.'],'Some past forms are irregular: go → went, not goed. Keep tense consistent unless the time changes.','Write one sentence about yesterday, one about a daily routine, and one using have or has plus a past participle.','Yesterday I played football. I read every evening. I have packed my bag.',[['Yesterday we ___ to the park.','went','go','goes','going','Went is the past form of go.'],['Every morning she ___ breakfast.','eats','ate','eating','eaten','She takes eats in the present simple.'],['Which is present perfect?','I have finished.','I finished yesterday.','I finish daily.','I am finishing.','Have + past participle.'],['Choose the correct past form of see.','saw','seed','seen alone','seeing','The past simple of see is saw.'],['Choose the consistent sentence.','He opened the box and smiled.','He opened the box and smiles yesterday.','He open the box and smiled.','He opening the box and smile.','Both completed actions use past tense.']]);
SL('spelling','English','Spelling: prefixes, suffixes and word families',Y,['A prefix is added at the beginning of a word; a suffix is added at the end. They can change meaning or word class.','Look for a familiar root and a spelling pattern. Check exceptions rather than assuming a rule always works.'],['Happy → unhappy: un- changes the meaning to not happy. Teach → teacher: -er makes a noun for a person who teaches.','Hope + -ing → hoping: drop the final e. Hop + -ing → hopping: double the final p to keep the short vowel pattern.'],'Hoping and hopping are different words. Say the word, consider its meaning, then check its spelling pattern.','Build four words from help using a prefix or suffix. Use two in sentences.','Helpful, helpless, helping, unhelpful. Example: Her helpful explanation made the task easier.',[['What does the prefix un- often mean?','not','again','before','under','Unhappy means not happy.'],['Which spelling means wanting something to happen?','hoping','hopping','hopeing','hoppping','Hope loses its final e before -ing.'],['Which has a suffix?','careful','uncare','replay','dislike','-ful is added to care.'],['Choose the correct spelling.','running','runing','runeing','runnning','Double the n before -ing in running.'],['Which word shares a root with teacher?','teaching','table','reach','cheer','Teach is the shared root.']]);
SL('paragraph','English','Writing: sentences, paragraphs and editing',Y,['A paragraph groups related ideas. Begin a new paragraph when the topic, time, place or speaker changes.','Plan what you want the reader to understand. Draft your ideas, improve the language, then proofread spelling and punctuation.'],['A recount about a trip might use paragraph 1 for arrival, paragraph 2 for what happened and paragraph 3 for the ending.','Draft: The dog was nice. Improved: The gentle dog rested its head on my knee. The detail helps a reader picture its behaviour.'],'Longer sentences are not always better. Each sentence needs a clear meaning; each paragraph needs a focus.','Write 6–8 sentences about something you learned today. Use two paragraphs. Underline one sentence you improved.','Check for a clear topic, linked ideas, accurate capitals and punctuation. There is no single correct response; a parent should review the writing.',[['When should you often start a new paragraph?','When the topic or speaker changes','After every word','Only after 100 words','Never','A new paragraph helps organise a change.'],['Which is a useful planning question?','Who is my reader and what do they need to know?','How can I use the longest words?','Can I avoid all punctuation?','How can I write without a purpose?','Audience and purpose guide your choices.'],['What is proofreading?','Checking errors in a draft','Writing random extra words','Ignoring spelling','Choosing a book cover','Proofreading checks spelling, punctuation and other slips.'],['Which sentence gives a specific detail?','The red kite twisted above the field.','It was a thing.','Something was there.','It was nice.','Specific nouns and verbs help the reader picture the scene.'],['Can an automatic multiple-choice score assess all of a written story?','No, a person must review the writing','Yes, always','Only its length matters','Only its font matters','Organisation, meaning and voice need direct review.']]);
SL('relative','English','Relative clauses and expanded noun phrases',[5,6],['A relative clause adds information about a noun, often using who, which, that, whose or where.','An expanded noun phrase adds detail to a noun: the old stone bridge. Choose details that help your meaning.'],['The scientist who discovered the fossil smiled. Who discovered the fossil tells us which scientist.','My bicycle, which has a red frame, is outside. The extra clause is set off with commas.'],'A relative pronoun must refer clearly to the intended noun. Commas depend on whether information is additional or identifying.','Add a relative clause to The girl won the race. Then expand the noun phrase a house.','The girl who trained every week won the race. A small, white house beside the river.',[['Choose a relative pronoun for a person.','who','because','and','although','Who can introduce information about a person.'],['Identify the relative clause: “The book that I borrowed was exciting.”','that I borrowed','The book','was exciting','borrowed was','The clause gives information about the book.'],['Which is an expanded noun phrase?','the tall, narrow tower','runs quickly','because it rained','and then','The noun tower has extra describing detail.'],['Complete: “The artist, ___ work we admired, waved.”','whose','because','which is','wherever','Whose shows the relationship to the artist’s work.'],['A relative clause usually…','adds information about a noun','makes every sentence a question','replaces all verbs','must start with because','It modifies or identifies a noun.']]);
SL('plants','Science','Plants: roots, stems, leaves and flowers',[3],['Roots anchor a plant and absorb water and minerals. The stem supports it and transports water. Leaves use light to help make food.','Flowers are involved in reproduction. Pollination transfers pollen; after fertilisation, seeds can form. Seeds need suitable conditions to germinate.'],['A wilted plant may need water, but one observation does not prove the cause. Check the soil and compare conditions.','To investigate water, use similar plants with the same light, pot and soil. Change the water amount and observe growth over time.'],'Plants do not eat soil. They use light to make food and absorb water and minerals through roots.','Draw a flowering plant. Label four parts and explain each job. Plan a fair comparison of plant growth.','Roots: absorb water/minerals and anchor; stem: support/transport; leaves: make food using light; flowers: reproduction. Change only one factor in the comparison.',[['Which part usually absorbs water from soil?','Roots','Petals','Seeds','Fruit','Roots absorb water and minerals.'],['Which part transports water up the plant?','Stem','Petal only','Pollen','Seed coat','Water moves through tubes in the stem.'],['What is pollination?','Transfer of pollen','Water leaving a pot','A rock breaking','A seed eating soil','Pollen is transferred between flower parts.'],['What helps many seeds germinate?','Water, oxygen and suitable warmth','Only bright paint','No air at all','Only dry sand','Conditions depend on species, but these are common requirements.'],['In a fair test of water amount, what should stay similar?','Plant type, light and soil','Nothing','Only the day’s name','The colour of the notebook','Keep other factors similar so the comparison is meaningful.']]);
SL('skeleton','Science','Animals and humans: nutrition, skeletons and muscles',[3],['Animals get nutrients by eating plants or other animals. A varied, balanced diet helps provide energy and materials for growth and repair.','The human skeleton supports the body and protects organs. Muscles pull on bones to cause movement; many work in opposing pairs.'],['The skull protects the brain. The ribcage helps protect the heart and lungs.','To bend your elbow, one main muscle contracts while its opposing muscle relaxes. Muscles pull rather than push.'],'Not every animal has an internal bony skeleton. Insects have an external skeleton.','Label skull, ribs, spine and thigh bone on a simple drawing. Explain why muscles are needed as well as bones.','Bones support/protect; muscles pull on them to move the body.',[['Which protects the brain?','Skull','Thigh bone','Finger bone','Pelvis only','The skull surrounds the brain.'],['How do muscles move bones?','By pulling','By pushing only','By dissolving them','By turning into bones','Contracting muscles pull on bones.'],['Why do animals need food?','For energy, growth and repair','Only to change colour','To make rocks','To stop all movement','Food supplies energy and nutrients.'],['Which has an external skeleton?','An insect','A human','A cat','A dog','An insect’s exoskeleton is outside its body.'],['Which is a skeleton function?','Supporting and protecting the body','Making sunlight','Absorbing soil','Producing rain','Skeletons give support and protect organs.']]);
SL('rocks','Science','Rocks, fossils and soils',[3],['Rocks have different properties such as hardness, texture and permeability. These properties affect how rocks are used.','Fossils are preserved evidence of past life. Soil can contain tiny rock particles, air, water and organic matter.'],['Compare two rocks by rubbing, observing grains and testing whether water soaks through. Record evidence rather than just naming colours.','A shell buried in sediment may leave an impression that is preserved as the sediment becomes rock over a long time.'],'A fossil is not always a complete bone. It can be an impression or trace.','Compare two stones safely by appearance and texture. Write an observation and a question you would investigate.','Example: Rock A has visible grains; Rock B looks smooth. Question: Does water soak through them at the same rate?', [['Which is evidence of past life?','A fossil','A new plastic cup','A painted pebble','A metal coin','Fossils preserve remains or traces of organisms.'],['Which can soil contain?','Rock particles and organic matter','Only sand','Only water','Only plastic','Soil is a mixture.'],['What does permeable mean?','Allows water through','Always black','Always heavy','Made yesterday','Permeability describes water passing through.'],['Which is an observation?','This rock has visible grains.','This must be the oldest rock ever.','All rocks are identical.','It is definitely from Mars.','Visible grains can be directly observed.'],['Fossil formation usually involves…','burial and preservation over a long time','painting a stone','melting plastic','one minute in a fridge','Some remains or traces become preserved in sedimentary rock.']]);
SL('light','Science','Light, shadows and reflection',[3,6],['We need light to see. Light enters our eyes directly from a source or after reflecting off an object.','An opaque object blocks light and can make a shadow. Light travels in straight lines. Never look directly at the Sun.'],['A torch shines on a book. Light reflects off the book into your eyes, allowing you to see it.','Move an object nearer a torch while keeping the screen fixed: its shadow usually grows because it blocks a larger spread of light.'],'The Moon reflects sunlight; it does not produce its own visible light. Eyes do not send light out to objects.','Use a torch, toy and wall to observe a shadow. Predict what changes when the toy moves nearer the torch.','The toy blocks light. With torch and wall fixed, moving the toy nearer the torch generally makes the shadow larger.', [['Which is a light source?','A lit torch','A mirror','An unlit book','The Moon','A lit torch produces light.'],['How do we see a book?','Light reflects from it into our eyes','Our eyes shoot light at it','It must glow by itself','Only by sound','Reflected light reaches our eyes.'],['What makes a shadow?','An object blocking light','An object making extra light','A sound wave','A transparent gap only','Opaque objects block light.'],['Which reflects sunlight?','The Moon','A switched-on lamp bulb','A candle flame','A lit screen','The Moon reflects rather than generates sunlight.'],['Is it safe to stare at the Sun?','No','Yes, with sunglasses always','Yes, at midday','Yes, for a long time','Direct viewing can damage eyes.']]);
SL('forces','Science','Forces, magnets and friction',[3,5],['A force is a push or pull. Friction acts between surfaces and opposes their relative motion.','Magnets can attract some materials, such as iron. Opposite magnetic poles attract; like poles repel. Gravity pulls objects towards Earth.'],['A toy car often rolls less far on a rough carpet than a smooth surface because friction differs.','Bring two north poles together: they repel. Bring a north and south pole together: they attract.'],'Not all metals are magnetic. Test materials rather than assuming a shiny object will be attracted.','Plan a comparison of how far a toy car travels on two surfaces. Keep the starting ramp and car the same.','Measure travel distance on each surface, repeat trials and compare. Change only the surface.', [['Like magnetic poles…','repel','always attract','turn into wood','have no effect ever','North–north and south–south repel.'],['Which is usually attracted to a magnet?','Iron nail','Wooden ruler','Plastic cup','Glass marble','Iron is magnetic.'],['Friction usually…','opposes movement between surfaces','always speeds everything up','makes every object magnetic','removes gravity','It acts against relative sliding.'],['A push or pull is a…','force','temperature','volume','colour','Force describes pushes and pulls.'],['What pulls a falling apple towards Earth?','Gravity','Only magnetism','Light','Sound','Earth’s gravity attracts the apple.']]);
function factsLesson(id,title,years,ex,worked,mistake,task,model,qs){SL(id,'Science',title,years,ex,worked,mistake,task,model,qs)}
factsLesson('states','States of matter and the water cycle',[4],['A solid usually keeps its shape; a liquid flows and takes the shape of its container; a gas spreads to fill available space.','Heating or cooling can change state. Evaporation changes liquid water to water vapour; condensation changes vapour to liquid.'],['Water on a warm pavement can evaporate. Water droplets on a cold window can form by condensation.','The water cycle includes evaporation, condensation and precipitation. Water vapour itself is invisible.'],'A cloud is tiny water droplets or ice particles, not simply invisible water vapour.','Draw and label evaporation, condensation and precipitation in a water cycle.','Water evaporates, vapour cools and condenses into droplets, then water falls as precipitation.', [['Ice is water in which state?','Solid','Gas','Liquid','Plasma','Ice usually keeps its shape.'],['Liquid water becoming gas is…','evaporation','freezing','condensation','melting','Evaporation changes liquid to gas.'],['Water vapour cooling into droplets is…','condensation','melting','boiling','freezing only','Gas changes to liquid.'],['Which takes the shape of its container but has a fixed volume?','A liquid','A solid block','A gas','A shadow','Liquids flow but do not expand to fill all available space.'],['Rain is a form of…','precipitation','evaporation','melting only','magnetism','Precipitation falls from clouds.']]);
factsLesson('digestion','Teeth, digestion and food chains',[4],['Teeth break food into smaller pieces. Saliva begins digestion; the stomach mixes food; nutrients are absorbed mainly in the small intestine.','A food chain shows feeding relationships. Arrows point from food towards the organism that gets energy from eating it.'],['Grass → rabbit → fox. The rabbit eats grass; the fox eats the rabbit.','Incisors cut, canines tear and molars grind food.'],'Food-chain arrows show energy transfer, not the direction the hunter runs.','Draw a food chain with a producer, herbivore and carnivore. Explain the arrows.','Grass → rabbit → fox. Grass is the producer; arrows show energy moving to the consumer.', [['Where are most nutrients absorbed?','Small intestine','Teeth','Oesophagus','Large intestine only','The small intestine absorbs most digested nutrients.'],['Which teeth grind food?','Molars','Only incisors','Only canines','No teeth','Broad molars crush and grind.'],['Grass in a food chain is a…','producer','top predator','carnivore','decomposer only','Plants make food using light.'],['In grass → rabbit, who eats the grass?','Rabbit','Grass','Neither','The arrow','Energy passes from grass to rabbit.'],['What does the oesophagus do?','Moves food towards the stomach','Pumps blood','Absorbs all oxygen','Makes bones','It is the tube carrying swallowed food to the stomach.']]);
factsLesson('sound','Sound and vibrations',[4],['Sounds are produced by vibrations. Vibrations travel through a medium such as air, water or a solid to the ear.','Faster vibrations give higher pitch. Bigger vibrations generally give louder sounds. Pitch and loudness describe different things.'],['Pluck a ruler over a desk edge. A shorter vibrating length usually vibrates faster and makes a higher pitch.','Pluck the same ruler harder: it vibrates with greater amplitude and sounds louder.'],'High pitch does not necessarily mean loud. Protect hearing from very loud sound.','Investigate ruler length and pitch. Keep how you pluck similar and describe what you hear.','Shorter vibrating lengths tend to give higher pitches; repeat to check the pattern.', [['Sound starts with…','vibrations','shadows','a colour','stillness only','A vibrating source makes sound.'],['Faster vibrations give…','higher pitch','lower pitch always','less gravity','a darker colour','Frequency affects pitch.'],['Greater vibration amplitude usually means…','louder sound','higher pitch always','no sound','colder air','Amplitude affects loudness.'],['Can sound travel through water?','Yes','No, only air','Only if frozen','Only as light','Sound can travel through liquids.'],['Which helps protect hearing?','Avoiding very loud sound','Putting an ear next to a loudspeaker','Turning volume fully up','Ignoring discomfort','Loud sound can harm hearing.']]);
factsLesson('electricity','Electricity and simple circuits',[4,6],['A simple circuit needs a power source and a complete conducting path. A bulb lights when current can flow through it.','A switch can open or close the path. Metals usually conduct electricity; plastic usually insulates. Use low-voltage batteries with adult supervision, never mains sockets.'],['A cell, wires and bulb form a closed loop. Remove one wire: the path breaks and the bulb goes out.','An open switch breaks the circuit. Closing it reconnects the conducting path.'],'Electricity is not used up by the first wire. A gap anywhere in a simple series circuit stops current.','Draw a circuit with a cell, bulb and switch. Show one open and one closed version.','Closed: one complete loop through components. Open: a gap at the switch; the bulb does not light.', [['A bulb in a simple series circuit needs…','a complete conducting loop','a gap in every wire','only one loose wire','no power source','Current needs a complete circuit.'],['An open switch…','breaks the circuit','always makes a bulb brighter','creates a new battery','removes the wire’s metal','The gap stops current in a simple series circuit.'],['Which usually conducts electricity?','Copper','Plastic','Rubber','Dry wood','Copper is a metal conductor.'],['Which is usually an insulator?','Plastic','Copper','Iron','Aluminium','Plastic is used around conducting wires.'],['For a home learning circuit, use…','low-voltage batteries with an adult','a mains socket','damaged mains wires','an outdoor power cable in water','Keep experiments to suitable low-voltage equipment.']]);
factsLesson('habitats','Living things, habitats and classification',[4,5,6],['A habitat provides conditions and resources an organism needs. Environmental change can help some organisms and harm others.','Classification groups organisms by shared features. A branching key uses questions with clear alternative answers.'],['A key might ask: Does it have six legs? If yes, it may be an insect. Then use more features to distinguish organisms.','Removing a hedge can remove shelter and food for birds and insects. Consider several effects, not just one.'],'A classification key identifies features, not whether an animal is nice or scary.','Make a two-question branching key for a butterfly, spider and snail.','Ask: Does it have legs? No → snail. Yes → six legs? Yes → butterfly; no → spider.', [['What is a habitat?','A place providing conditions and resources for an organism','Only a cage','Only a building','A type of food','Habitats include resources and suitable conditions.'],['An insect typically has how many legs?',6,8,4,10,'Adult insects have six legs.'],['Which is a useful key question?','Does it have wings?','Is it lovely?','Do I like it?','Is it interesting?','Observable features make a reliable key.'],['Removing a hedge can…','remove food and shelter','help every organism equally','have no possible effect','make all birds extinct immediately','Local resources can be affected.'],['Classification groups by…','shared features','only size of a name','personal favourites','random choices','Shared features help organise living things.']]);
factsLesson('materials','Properties and changes of materials',[5],['Materials have properties such as hardness, transparency, conductivity and solubility. Choose materials for a job using evidence.','Dissolving mixes a solute into a solvent. Some changes are reversible, such as melting/freezing; changes forming new substances are often difficult to reverse.'],['Salt dissolves in water. Evaporating the water can recover salt. Sand does not dissolve and can be separated by filtration.','Burning wood produces new substances. It cannot be changed back into the original wood by cooling.'],'Dissolving is not melting: melting needs a state change, while dissolving mixes substances.','Describe how to separate a sand-and-water mixture, then how to recover salt from salty water.','Filter sand from water; evaporate water to recover salt with suitable adult supervision, without tasting or unsafe heating.', [['Which separates sand from water?','Filtration','A magnet always','Freezing only','Painting','A filter traps insoluble sand.'],['Salt in water can be recovered by…','evaporating the water','adding more sand','stirring forever','using a large sieve alone','Water leaves as vapour, leaving salt.'],['Which is usually reversible?','Melting ice','Burning wood','Cooking an egg','Rusting a nail','Water can freeze into ice again.'],['Transparent means…','allows light through so objects can be seen clearly','always soft','magnetic','waterproof','Transparency describes light passing through.'],['Dissolving and melting are…','different processes','always identical','both only burning','both impossible','Dissolving involves mixing with a solvent.']]);
factsLesson('space','Earth, Moon, Sun and space',[5],['Earth rotates on its axis, giving day and night. It orbits the Sun in about one year. The Moon orbits Earth.','The Sun is a star. Earth and the other planets orbit the Sun. The apparent daily movement of the Sun is mainly caused by Earth’s rotation.'],['A torch shining on a ball models day and night. The lit side has day; as the ball rotates, different places face the light.','Earth makes one rotation in about 24 hours and an orbit in about 365¼ days.'],'Seasons are not simply caused by Earth being nearer the Sun. Earth’s tilted axis changes sunlight angle and day length.','Use a ball and torch to explain why it is day in one place and night elsewhere.','One side faces the Sun while the other faces away; Earth’s rotation changes which side faces the Sun.', [['What mainly causes day and night?','Earth rotating','The Sun orbiting Earth daily','Clouds switching off sunlight','The Moon glowing','Earth turns on its axis.'],['Earth orbits the…','Sun','Moon','North Pole','clouds','Earth is a planet orbiting the Sun.'],['The Moon orbits…','Earth','Mars only','the North Pole','clouds','The Moon is Earth’s natural satellite.'],['One Earth rotation takes about…','24 hours','1 hour','1 year','1 month','A day corresponds approximately to a full rotation.'],['The Sun is a…','star','planet','moon','comet','The Sun produces energy and light as a star.']]);
factsLesson('circulation','Human circulation and healthy choices',[6],['The heart pumps blood through vessels. Blood carries oxygen and nutrients and takes away waste products.','Lungs transfer oxygen into blood and remove carbon dioxide. Exercise increases the body’s demand for oxygen, so heart and breathing rates often rise.'],['After gentle activity, count pulse for the same length of time as at rest. Compare readings without treating one small experiment as a diagnosis.','Arteries carry blood away from the heart; veins carry it towards the heart.'],'Arteries are defined by direction, not simply by always carrying oxygen-rich blood.','Explain the different jobs of heart, blood vessels and lungs.','Heart pumps; vessels carry blood; lungs exchange oxygen and carbon dioxide.', [['Which organ pumps blood?','Heart','Stomach','Small intestine','Kidney only','The heart contracts to pump blood.'],['Arteries carry blood…','away from the heart','always towards the heart','only to teeth','only when sleeping','Direction defines arteries.'],['Where does oxygen enter blood from the air?','Lungs','Stomach','Skin only','Bones','Gas exchange occurs in lungs.'],['During exercise, pulse often…','increases','stops','becomes zero','always halves','Muscles need more oxygen and energy.'],['Blood carries…','oxygen and nutrients','only air bubbles','only water','only food pieces','Blood transports dissolved substances and cells.']]);
factsLesson('evolution','Evolution, inheritance and adaptation',[6],['Offspring inherit characteristics from parents, but are not identical. Variation can also result from environment.','Over many generations, inherited variations that help survival and reproduction can become more common. Adaptations suit organisms to particular conditions.'],['A bird with a beak suited to available food may be more likely to survive and reproduce, passing on inherited traits.','A scar is acquired during life. It is not inherited in the same way as a genetic characteristic.'],'An individual does not decide to evolve a new feature because it needs one. Evolution concerns populations across generations.','Explain one adaptation of a desert plant and how it may help. Distinguish an inherited feature from an acquired one.','Thick stems may store water. Inherited feature: eye colour influenced by genes; acquired feature: a scar.', [['Evolution occurs across…','many generations','one decision by an animal','one afternoon always','a single meal','Changes accumulate in populations over generations.'],['Which is acquired during life?','A scar','Inherited blood group','Inherited gene variant','Genetic parentage','Scars result from injury.'],['An adaptation can…','help an organism survive in particular conditions','work equally well everywhere','appear by conscious choice','remove all variation','Suitability depends on environment.'],['Fossils can provide…','evidence of past organisms','a full film of every past event','proof all species are identical','only modern weather reports','Preserved remains or traces inform us about past life.'],['Offspring are…','similar to parents but not identical','always exact copies','unrelated to inherited traits','never affected by environment','Inheritance and variation both matter.']]);
SL('history','History','Historical sources and timelines',Y,['History studies the past using evidence. A primary source comes from the time being studied; a secondary source is a later account.','Put events in chronological order, from earliest to latest. A source may tell only part of the story; compare sources and ask who made them and why.'],['A diary written by a child during a historical event is a primary source. A modern textbook describing the event is secondary.','A photograph may show clothing and buildings, but it cannot tell us every person’s thoughts.'],'Old does not automatically mean accurate. A source can be useful and still be biased or incomplete.','Use your school’s current history unit. Choose an object, picture or text. Write what it shows, what you infer and one question it cannot answer.','Separate observation from inference. Example: the photo shows uniforms; I infer a group role; it does not reveal everyone’s feelings.', [['Chronological order means…','earliest to latest','largest to smallest','alphabetical order','favourite first','Chronology orders events in time.'],['Which is a primary source for a past event?','A diary written at the time','A modern film about it','A recent textbook chapter','A new imaginary story','It was created during the period.'],['Why compare sources?','To check different evidence and viewpoints','To avoid all evidence','Because every source says the same','Only to find the longest','Different sources reveal different details and limitations.']]);
SL('geography','Geography','Maps, directions and physical or human features',Y,['A map represents a place using symbols, a key and often a scale. Compass directions help describe where things are.','Physical features are natural, such as rivers and hills. Human features are built or shaped by people, such as roads and bridges.'],['If a school is north of a park, the park is south of the school. A map key explains what symbols mean.','A river is a physical feature; a bridge crossing it is a human feature.'],'A map symbol is not a full-size picture. Check its key and orientation.','Draw a simple map of the route to school without your house number. Include a key, north arrow and one physical and human feature.','Check consistent symbols and directions. Example: trees or a stream are physical; roads and buildings are human.', [['Which is a physical feature?','River','Road','Bridge','Factory','A river occurs naturally.'],['Which explains map symbols?','Key','Title alone','Page number','Date alone','The key matches symbols to meanings.'],['Opposite of north?','South','East','West','North-east','North and south are opposite directions.'],['Which is a human feature?','Railway station','Mountain','Valley','Sea','A railway station is built by people.']]);
SL('computing','Computing','Algorithms, debugging and online safety',Y,['An algorithm is a clear sequence of steps for a task. A program expresses instructions a computer can follow.','Debugging means finding and fixing errors. Predict what should happen, run or trace the instructions, compare the result and change the faulty step.'],['Algorithm for drawing a square: repeat four times: move forward the same distance, then turn right 90°.','If the turn is 45°, the drawing will not close as a square. Change the angle and test again.'],'Computers follow the instructions supplied, not what we meant. Keep passwords and personal details private, and tell a trusted adult about upsetting contact.','Write steps to make a character draw a square. Deliberately change one step, predict the result, then debug it on paper.','Four equal moves with four right-angle turns make a square. Correct the faulty turn or distance.', [['An algorithm is…','a clear sequence of steps','only a screen','a secret password','a random picture','Algorithms describe a process.'],['Debugging means…','finding and fixing errors','deleting all work always','sharing a password','switching off every device','Compare intended and actual behaviour.'],['An unknown person online asks for your address. You should…','not share it and tell a trusted adult','send it immediately','send a friend’s address','post it publicly','Protect personal details and ask for help.'],['A square needs four turns of…','90°','45°','10°','180°','Four right-angle turns complete a full turn.']]);
SL('art','Art & Design','Drawing, shading and observing detail',Y,['Observe shapes, edges and proportions before adding details. A sketchbook helps record experiments and ideas.','Shading uses changes of tone to suggest form and light. Lighter areas face the light; darker areas may face away or lie in shadow.'],['Draw an apple first as a simple outline. Add a mid-tone, leave a highlight and shade the side facing away from the light.','Press a pencil gently for a light tone, then build darker tone in layers.'],'An object need not be outlined with a heavy dark line everywhere. Look carefully at what you can actually see.','Sketch a safe household object. Use three different tones and write where the light comes from.','A parent checks observation, range of tone and the explanation. Art has multiple successful outcomes.', [['Tone in drawing refers to…','lightness and darkness','only size','only sound','the price of paper','Tone can suggest form and lighting.'],['A sketchbook is useful for…','exploring and recording ideas','only perfect finished pictures','avoiding experiments','copying without looking','Sketchbooks support development.'],['A highlight is usually…','a light area reflecting more light','always the darkest mark','a hole in the paper','a caption only','Highlights help indicate the light source.']]);
SL('dt','Design & Technology','Design, make, test and improve',Y,['Design begins with a user and purpose. Write criteria describing what a successful product must do.','Choose materials for their properties, make a model, test against the criteria and improve it using evidence.'],['Design a paper bridge to span a 15 cm gap and hold three coins. Folding paper can improve stiffness without changing the material.','Test a flat and a folded bridge with the same gap and load. Compare before choosing a design.'],'A product looking attractive does not prove it works. Test its purpose and consider safe use.','Design a paper bridge with an adult. Sketch it, list two criteria, test it and write one improvement.','Criteria might include spanning the gap and holding a specified load. Record what happened; suggest a change based on the test.', [['What should a design begin with?','A user and purpose','Only a colour','A random purchase','No plan','Purpose guides design choices.'],['A design criterion is…','a requirement for success','only a drawing tool','a type of glue','an unrelated fact','Criteria let you evaluate the product.'],['After testing a model you should…','use results to improve it','ignore what happened','assume it is perfect','change everything randomly','Evidence guides improvement.']]);
SL('music','Music','Pulse, rhythm and musical patterns',Y,['Pulse is the steady beat. Rhythm is the pattern of long and short sounds placed against it.','Pitch describes how high or low a sound is; tempo describes how fast the music goes; dynamics describe loudness.'],['Keep a steady four-beat pulse while clapping the rhythm of your name. The rhythm may change while the beat stays steady.','A tune can be played quietly at a fast tempo: quiet does not mean slow.'],'Do not confuse pitch with volume, or pulse with rhythm.','Tap a steady beat and clap a short repeating pattern. Change its dynamics while keeping the tempo steady.','A parent listens for a steady pulse, a repeatable rhythm and a deliberate change of loudness.', [['A steady beat is the…','pulse','pitch','volume','lyric','Pulse is the underlying regular beat.'],['Tempo means…','speed','loudness','pitch','instrument colour','Tempo describes how fast music moves.'],['Dynamics describe…','loudness','only speed','only note names','the room size','Dynamics concern soft and loud.']]);
SL('pe','Physical Education','Movement, balance and safe practice',Y,['Balance means controlling body position while still or moving. A wider stable base can make balancing easier.','Warm up gradually, use a clear safe space and stop if an activity hurts. Practise technique and control before speed.'],['Balance with two feet apart, then try a narrower base near a stable support. Notice how your body adjusts.','In a throw, look at the target, step towards it and follow through. Use a soft ball in a suitable space.'],'Faster is not always better. Safe technique and controlled movement come first.','With an adult, choose a safe balance or soft-ball skill. Set one small goal, practise and describe what improved.','Review control, safe spacing and the chosen technique. Adapt to ability; a quiz cannot assess physical skill.', [['What is a sensible first step before activity?','Check space and warm up gradually','Sprint without checking','Ignore obstacles','Continue through pain','Prepare safely and build effort gradually.'],['Balance involves…','controlling body position','only running fast','holding breath','closing eyes in every task','Control supports stability.'],['What should you do if an activity hurts?','Stop and tell an adult','Always push harder','Hide it','Repeat immediately','Pain needs attention and activity may need adapting.']]);
SL('french','Languages','French: greetings and introducing yourself',Y,['Bonjour means hello or good day. Au revoir means goodbye. Merci means thank you.','Je m’appelle… means My name is… Listen to a reliable speaker or school audio and practise a little at a time.'],['Bonjour, je m’appelle Léa. → Hello, my name is Léa.','Comment tu t’appelles ? → What is your name? Reply: Je m’appelle…'],'French sounds do not always match English spelling. Use school audio to check pronunciation.','Write a short greeting and introduction in French, then say it to someone.','Bonjour ! Je m’appelle [name]. Au revoir ! Adapt this introductory lesson if her school teaches a different language.', [['Bonjour means…','Hello','Goodbye','Thank you','Please','Bonjour is a greeting.'],['Merci means…','Thank you','Hello','Monday','Good night','Merci expresses thanks.'],['Je m’appelle… means…','My name is…','I am hungry','I live in London','Goodbye','Use it to introduce your name.']]);
SL('re','Religious Education','Christianity: the Good Samaritan and caring for others',Y,['Religious Education explores beliefs, practices and questions about meaning. Use the school’s actual religious or locally agreed syllabus.','In the Christian parable of the Good Samaritan, an injured traveller is helped by a Samaritan after others pass by. Many Christians connect the story with loving one’s neighbour.'],['A lesson question: What does the Samaritan do that shows care? Answer: he stops, treats the injured person and arranges further help.','A reflection: helping someone excluded from a group can be an everyday example of showing care.'],'A quiz can check understanding of a story, but should not grade a child’s personal beliefs.','Retell the story briefly. Give one example of care and explain how it connects to the story.','Mention the injured traveller, the helper and practical support. Accept thoughtful personal reflections without scoring belief.', [['Who helps the injured traveller in the parable?','The Samaritan','Every passer-by','Nobody','A modern bus driver','The Samaritan stops to give practical help.'],['Which action best shows care?','Stopping and arranging help','Walking past without looking','Mocking an injury','Taking the traveller’s belongings','The helper responds to the person’s need.'],['A fair RE assessment checks…','understanding and thoughtful explanation','whether a child holds a required personal belief','only handwriting','family background','Assess learning, not personal faith.']]);
SL('pshe','PSHE / Relationships','Friendship, feelings and asking for help',Y,['Feelings give information, but different people can feel differently about the same event. Name a feeling and think about a safe response.','Respectful friends listen, include others and accept boundaries. A trusted adult can help when someone feels unsafe, pressured or persistently upset.'],['If a friend wants quiet time, you can respect the boundary and offer to talk later.','If a child is excluded repeatedly, write down what happened and ask a trusted adult for support.'],'A child should not have to keep a secret that makes them feel unsafe. Asking for help is appropriate.','Write two respectful ways to respond when someone disagrees with you. Name a trusted adult you can ask for help without entering private details here.','Examples: listen without interrupting; say I see it differently because…; ask an adult when needed.', [['A respectful friend should…','listen and respect boundaries','demand every secret','always choose for others','exclude someone repeatedly','Friendship includes respect and choice.'],['If a secret makes you feel unsafe, you should…','tell a trusted adult','keep it at all costs','post private details online','blame yourself','Seek help from a trusted adult.'],['Can two people feel differently about the same event?','Yes','No','Only adults can','Only if one is wrong','People have different experiences and feelings.']]);
